async function dataPage(gen){const d=await api('/admin/overview');if(gen!==state.generation)return;$('#main').innerHTML=heading('为每一份记录，留好副本。','查看备份状态，或导出攻略和旅行足迹供自己保存。')+`<div class="settings-width"><section class="panel"><h2>数据库与自动备份</h2><dl class="backup-info"><dt>当前数据库</dt><dd>${esc(d.database)}</dd><dt>最近成功备份</dt><dd>${d.backup?date(d.backup.created_at):'尚无备份记录'}</dd><dt>备份文件</dt><dd>${esc(d.backup?.filename||'—')}</dd><dt>计划</dt><dd>每天 03:15 左右，保留最近 7 份</dd><dt>内容</dt><dd>数据库、上传图片与 HTML、代码、配置及恢复说明</dd><dt>保存位置</dt><dd>当前服务器本地；服务器外副本需另行保存</dd></dl><p class="help">完整备份和恢复由服务器管理员操作。恢复前应先在独立数据库验证，避免覆盖新内容。</p></section><section class="panel"><h2>导出全部旅行内容</h2><p class="muted">导出全部攻略、旅行足迹、分类和站点设置，包括草稿、私密及回收站内容。JSON 文件可离线存档，图片文件与登录凭据不包含在内容导出中。</p><a class="button secondary" href="/api/admin/export" download>下载旅行内容 JSON</a></section></div>`;}
const actionNames={'travel_agent.submit':'提交旅游需求','travel_agent.cancel':'停止攻略生成','travel_agent.save':'存档 AI 攻略','travel_agent.publish':'发布助手攻略','agent.submit':'提交管家任务','agent.cancel':'停止管家任务','agent.publish_request':'请求发布代码','agent.rollback_request':'请求回退代码','record.create':'新建旅行足迹','record.update':'编辑旅行足迹','record.trash':'足迹移入回收站','record.restore':'恢复旅行足迹','record.purge':'彻底删除旅行足迹','account.login':'管理员登录','account.logout':'退出登录','account.username_change':'修改登录账号','account.password_change':'修改密码','account.profile_update':'更新账号信息','guide.import_html':'导入 HTML 攻略','guide.create':'新建攻略','guide.update':'编辑攻略','guide.quick_update':'修改攻略分类／状态','guide.trash':'移入回收站','guide.restore':'恢复攻略','guide.bulk_public':'批量发布','guide.bulk_private':'设为私密','guide.bulk_draft':'转为草稿','guide.bulk_trash':'移入回收站','guide.bulk_restore':'恢复攻略','guide.bulk_purge':'彻底删除攻略','taxonomy.create':'新增分类／标签','taxonomy.rename':'重命名分类／标签','taxonomy.delete':'删除分类／标签','media.upload':'上传图片','media.rename':'重命名图片','media.trash':'图片移入回收站','media.bulk_trash':'批量删除图片（可恢复）','media.bulk_restore':'批量恢复图片','media.restore':'恢复图片','settings.update':'更新站点设置','data.export':'导出攻略','database.migrate':'数据库迁移','account.password_reset':'服务器重设密码'};
async function auditPage(gen){const d=await api('/admin/audit?page='+state.auditPage);if(gen!==state.generation)return;$('#main').innerHTML=heading('每次整理，都有记录。','追溯内容和设置的变更，记录中不包含密码。')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象与详情</th></tr></thead><tbody>${d.logs.map(l=>`<tr><td class="table-meta">${date(l.created_at)}</td><td>${esc(l.actor)}</td><td class="audit-action">${esc(actionNames[l.action]||l.action)}</td><td class="audit-detail">${esc(l.target)} ${esc((l.action==='account.username_change'?l.details.old_username+' → '+l.details.new_username:'')||l.details.title||l.details.name||l.details.titles?.join('、')||JSON.stringify(l.details))}</td></tr>`).join('')}</tbody></table></div>${pager(d,'audit-page')}</section>`;}
function showDialog(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
async function picker(target){state.pickerTarget=target;const d=await api('/admin/media');const rows=[...d.media.filter(m=>!m.deleted_at),...d.defaults];showDialog(`<h2>${target==='cover'?'选择封面':'插入正文图片'}</h2><div class="actions" style="margin-bottom:20px">${button('上传新图片','upload',`data-value="${target}"`,'secondary')}</div><div class="picker-grid">${rows.map(m=>`<button type="button" class="picker-card" data-action="choose-image" data-url="${esc(m.url)}"><img src="${esc(adminThumbnail(m.url))}" alt="${esc(m.name)}" loading="lazy" decoding="async" width="640" height="480"><span>${esc(m.name)}</span></button>`).join('')}</div>`);}
function chooseImage(url,target){if(target==='cover'){const form=$('#editor-form');form.elements.cover.value=url;$('#editor-cover').src=editorImage(url,state.editor);state.dirty=true;$('#editor-status').textContent='封面已修改，请保存攻略。';}if(target==='body'){TravelEditor.insertImage(url);}$('#dialog').close();}
async function saveEditor(draft=false){if(TravelEditor.busy){toast('请等待编辑器加载或图片上传完成。');return;}TravelEditor.sync();const form=$('#editor-form');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.days=Number(data.days);data.category_id=data.category_id?Number(data.category_id):null;data.tags=data.tags.split(/[,，\n]/).map(t=>t.trim()).filter(Boolean);data.sample=form.elements.sample.checked;if(draft)data.status='draft';if(state.editor.id)data.revision=state.editor.revision;const buttons=[...document.querySelectorAll('button[type=submit],button[data-action=save-draft]')];buttons.forEach(b=>b.disabled=true);$('#editor-error').textContent='';try{const result=await api(state.editor.importToken?'/admin/html-imports/'+state.editor.importToken+'/save':'/guides'+(state.editor.id?'/'+state.editor.id:''),{method:state.editor.id?'PUT':'POST',body:data});state.dirty=false;toast('攻略已保存');if(location.hash==='#edit/'+result.id)await route();else location.hash='edit/'+result.id;}catch(e){$('#editor-error').textContent=e.message;toast(e.message,true);}finally{buttons.forEach(b=>b.disabled=false);}}
async function bulk(action,ids){if(!ids.length)return;const labels={public:'发布',draft:'转为草稿',private:'设为私密',trash:'移入回收站',restore:'恢复',purge:'彻底删除'};if(!confirm(`确定将选中的 ${ids.length} 篇攻略${labels[action]}？${action==='purge'?'此操作无法从回收站恢复。':''}`))return;await api('/admin/guides/bulk',{method:'POST',body:{action,ids}});toast('已完成'+labels[action]);await route();}
async function route(){if(!state.user){showLogin();return;}const hash=location.hash.slice(1)||'dashboard';if((state.mediaBusy||FootprintsAdmin.busy||TravelEditor.busy)&&hash!==state.route){history.replaceState(null,'','#'+state.route);toast('照片正在上传或记录正在保存，请稍候。');return;}if(state.dirty&&hash!==state.route){if(!confirm('有未保存的改动，确定离开？')){history.replaceState(null,'','#'+state.route);return;}state.dirty=false;}cancelAdminReads();TravelEditor.destroy();TravelAgent.stop();TravelPlanner.stop();const old=state.route;if(old===hash)clearAdminData();state.route=hash;let [view,id]=hash.split('/');if(!['dashboard','guides','trash','new','edit','records','record-new','record-edit','record-trash','import','taxonomy','media','settings','data','audit','account','agent','travel-agent'].includes(view))view='dashboard';if(['edit','record-edit'].includes(view)&&!/^\d+$/.test(id||'')){location.hash='guides';return;}if(['guides','trash'].includes(view)&&old!==hash)state.page=1;if(['records','record-trash'].includes(view)&&old!==hash)FootprintsAdmin.reset();const gen=++state.generation;shell(view);const main=$('#main'),previous=main.firstChild;main.inert=true;main.setAttribute('aria-busy','true');const rendered=new MutationObserver(()=>{if(gen===state.generation&&main.firstChild!==previous&&!main.querySelector('.initial-loading')){main.inert=false;main.removeAttribute('aria-busy');}});rendered.observe(main,{childList:true});const loading=setTimeout(()=>{if(gen===state.generation&&main.firstChild===previous)main.innerHTML='<div class="initial-loading">正在加载…</div>';},120);try{if(view==='taxonomy'){const tax=await api('/admin/taxonomy');if(gen!==state.generation)return;state.tax=tax;}if(view==='travel-agent')await TravelPlanner.page(gen,id);else if(view==='agent')await TravelAgent.page(gen);else if(view==='dashboard')await dashboard(gen);else if(view==='guides'||view==='trash')await guideList(view==='trash',gen);else if(view==='new'||view==='edit')await editor(view==='edit'?id:null,gen);else if(view==='records'||view==='record-trash')await FootprintsAdmin.list(view==='record-trash',gen);else if(view==='record-new'||view==='record-edit')await FootprintsAdmin.editor(view==='record-edit'?id:null,gen);else if(view==='import')await htmlImport(id,gen);else if(view==='taxonomy')await taxonomy(gen);else if(view==='media')await media(gen);else if(view==='settings')await settings(gen);else if(view==='account')await account(gen);else if(view==='data')await dataPage(gen);else if(view==='audit')await auditPage(gen);window.scrollTo(0,0);}catch(e){if(gen===state.generation&&state.user&&e.name!=='AbortError')$('#main').innerHTML=empty('页面暂时无法加载',e.message)+'<div class="actions">'+button('重新加载','retry-page','','primary')+'</div>';}finally{clearTimeout(loading);rendered.disconnect();if(gen===state.generation){main.inert=false;main.removeAttribute('aria-busy');}}}
document.addEventListener('click',async e=>{const node=e.target.closest('[data-action]');if(!node)return;const a=node.dataset.action,v=node.dataset.value;try{if(a==='discard-import'){await api('/admin/html-imports/'+v,{method:'DELETE'});state.dirty=false;location.hash='import';toast('已放弃这次预览');}if(a==='logout'){if(TravelEditor.busy){toast('请等待编辑或上传完成。');return;}if(state.dirty&&!confirm('有未保存的改动，确定退出？'))return;await api('/logout',{method:'POST'});state.user=null;state.dirty=false;await init();}if(a==='reset-filters'){state.filters={q:'',status:'',category:'',tag:''};state.page=1;await route();}if(a==='guide-page'){state.page=Number(node.dataset.page);await route();}if(a==='audit-page'){state.auditPage=Number(node.dataset.page);await route();}if(a==='bulk')await bulk(v,[...state.selected]);if(a==='single-bulk')await bulk(v,[Number(node.dataset.id)]);if(a==='close-dialog')$('#dialog').close();if(a==='save-draft')await saveEditor(true);if(a==='format'){const el=$('#editor-body');const selected=el.value.slice(el.selectionStart,el.selectionEnd);const txt=v==='heading'?`\n## ${selected||'小节标题'}\n`:v==='bold'?`**${selected||'重点内容'}**`:`\n- ${selected||'清单内容'}\n`;el.setRangeText(txt,el.selectionStart,el.selectionEnd,'end');el.focus();state.dirty=true;$('#editor-status').textContent='有未保存的改动。';}if(a==='apply-template')await applyTemplate();if(a==='preview-template')await previewTemplate();if(a==='preview'){TravelEditor.sync();const d=await api(state.editor?.importToken?'/admin/html-imports/'+state.editor.importToken+'/preview':'/admin/preview',{method:'POST',body:{body:$('#editor-body').value}});showDialog('<h2>正文预览</h2><div class="prose">'+d.html+'</div>');}if(a==='picker'){TravelEditor.remember();await picker(v);}if(a==='choose-image')chooseImage(node.dataset.url,state.pickerTarget);if(a==='upload'){state.uploadTarget=v;$('#upload-file').click();}if(a==='media-bulk')await bulkMedia(v);if(a==='media-clear'){for(const box of document.querySelectorAll('.media-check'))box.checked=false;updateMediaSelection();}if(a==='media-tab'){state.mediaTab=v;state.mediaPage=1;await route();}if(a==='media-page'){state.mediaPage=Number(node.dataset.page);renderMedia();$('#media-grid').scrollIntoView({block:'start'});}if(a==='retry-page'||a==='refresh-page')await route();if(a==='view-image')showDialog(`<h2>图片预览</h2><img src="${esc(adminThumbnail(node.dataset.url,1280))}" style="width:100%;max-height:65vh;object-fit:contain" alt="素材预览">`);if(a==='media-rename')showDialog(`<h2>重命名素材</h2><form id="media-name-form" data-file="${node.dataset.file}">${field('name','素材名称',node.dataset.name,'required maxlength="150"')}<button class="button primary" type="submit">保存名称</button></form>`);if(a==='media-update'){if(v==='trash'&&!confirm('删除这张图片？将移入素材回收站，可恢复。'))return;await api('/admin/media/'+node.dataset.file,{method:'POST',body:{action:v}});toast('素材已更新');await route();}if(a==='media-refs'){const m=state.media.media.find(m=>m.filename===node.dataset.file);showDialog(`<h2>这张图片的使用位置</h2>${m.references.map(r=>`<p><a href="#${r.kind==='travel-agent'?'travel-agent/'+r.id:r.kind==='record'?(r.deleted_at?'record-trash':'record-edit/'+r.id):(r.deleted_at?'trash':'edit/'+r.id)}" data-action="close-dialog">${esc(({'guide':'攻略','record':'旅行足迹','travel-agent':'旅游助手'})[r.kind]||'内容')} · ${esc(r.title)}${r.deleted_at?'（回收站）':''} →</a></p>`).join('')}`);}if(a==='taxonomy-form'){const old=node.dataset.name||'';showDialog(`<h2>${old?'重命名':'新增'}${node.dataset.kind==='tag'?'标签':'分类'}</h2><form id="taxonomy-form" data-kind="${node.dataset.kind}" data-id="${node.dataset.id||''}" data-old="${esc(old)}">${field('name','名称',old,`required maxlength="${node.dataset.kind==='tag'?24:40}"`)}<button class="button primary" type="submit">保存</button></form>`);}if(a==='taxonomy-delete'){if(!confirm(`删除“${node.dataset.name}”？攻略会保留，相关分类或标签将被移除。`))return;await api('/admin/taxonomy',{method:'POST',body:{kind:node.dataset.kind,action:'delete',id:node.dataset.id,old:node.dataset.name}});toast('已删除');await route();}}catch(err){toast(err.message,true);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-guide-field]')){saveGuideField(e.target);return;}if(e.target.id==='guide-template'){$('#template-description').textContent=GuideTemplates.catalog.find(t=>t.id===e.target.value).description;return;}if(e.target.id==='select-all'){document.querySelectorAll('.guide-check').forEach(c=>{c.checked=e.target.checked;const id=Number(c.value);if(c.checked)state.selected.add(id);else state.selected.delete(id);});}else if(e.target.classList.contains('guide-check')){const id=Number(e.target.value);if(e.target.checked)state.selected.add(id);else state.selected.delete(id);}else return;const all=[...document.querySelectorAll('.guide-check')];$('#select-all').checked=all.length>0&&all.every(c=>c.checked);$('#select-all').indeterminate=state.selected.size>0&&state.selected.size<all.length;$('#bulk-bar').hidden=!state.selected.size;$('#selected-count').textContent=`已选择 ${state.selected.size} 篇攻略`;});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(f.id==='html-import-form'){await uploadHtml(f);return;}if(f.id==='editor-form'){await saveEditor();return;}const data=Object.fromEntries(new FormData(f));const btn=$('button[type=submit]',f);if(btn)btn.disabled=true;try{if(f.id==='login-form'){$('#login-error').textContent='';const d=await api('/login',{method:'POST',body:data});state.user=d.user;state.csrf=d.csrf;f.password.value='';await route();}if(f.id==='filter-form'){state.filters=data;state.page=1;await route();}if(f.id==='taxonomy-form'){await api('/admin/taxonomy',{method:'POST',body:{...data,kind:f.dataset.kind,id:f.dataset.id,old:f.dataset.old,action:f.dataset.old?'rename':'create'}});$('#dialog').close();toast('已保存');await route();}if(f.id==='media-name-form'){await api('/admin/media/'+f.dataset.file,{method:'POST',body:{action:'rename',name:data.name}});$('#dialog').close();toast('素材名称已更新');await route();}if(f.id==='settings-form'){data.show_samples=f.show_samples.checked;await api('/admin/settings',{method:'PUT',body:data});toast('站点设置已保存');}if(f.id==='account-form'){const d=await api('/admin/account',{method:'PUT',body:data});f.reset();if(d.reauthenticate){state.user=null;state.csrf=d.csrf;$('#login-form [name=username]').value=d.username;$('#login-form [name=password]').value='';$('#login-error').textContent='';showLogin();toast('登录信息已更新，请重新登录');}else{const s=await api('/session');state.user=s.user;toast('账号信息已保存');await route();}}}catch(err){if(f.id==='login-form')$('#login-error').textContent=err.message;if(f.id==='account-form')$('#account-error').textContent=err.message;toast(err.message,true);}finally{if(btn)btn.disabled=false;}});
$('#upload-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50*1024*1024)throw new Error('图片不能超过 50 MB');toast('正在上传图片…');const form=new FormData();form.append('image',file);const d=await api('/upload',{method:'POST',body:form});if(state.uploadTarget==='media')await route();else chooseImage(d.url,state.uploadTarget);toast('图片上传成功');}catch(err){toast(err.message,true);}finally{e.target.value='';}});
window.addEventListener('hashchange',route);window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
async function init(){try{const d=await api('/session');state.csrf=d.csrf;state.user=d.user;if(state.user)await route();else showLogin();}catch(e){$('#loading').textContent='暂时无法连接管理后台，请刷新重试。';toast(e.message,true);}}
init();

window.openBodyImagePicker=()=>picker('body');
